## Summary

I have noticed some inconsistencies with the value of a `ContextVar`, and have managed to replicate a simple example below.

The TL;DR appears to be that FastAPI treats _synchronous_ dependencies in a separate thread to the one handling the request, thereby causing issues with the way `ContextVar` handles values internally. The same issue is _not_ present with asynchronous dependencies.

## Example Code

```python
from __future__ import annotations

import asyncio
import time
from contextvars import ContextVar
from random import randint
from typing import Annotated, Any

from fastapi import Depends, FastAPI

app = FastAPI()

test_var: ContextVar[str | None] = ContextVar("test_var", default=None)


def sf() -> tuple[str | None, str]:
    """
    Sync fixture to set `test_var`.
    """
    old_value = test_var.get()
    new_value = f"sf-{randint(0, 100):03d}"
    test_var.set(new_value)
    return old_value, new_value


async def af() -> tuple[str | None, str]:
    """
    Async fixture to set `test_var`.
    """
    old_value = test_var.get()
    new_value = f"af-{randint(0, 100):03d}"
    test_var.set(new_value)
    return old_value, new_value


@app.get("/sr-{id}")
def get_sr(id: int) -> dict[str, Any]:
    """
    Synchronous request with test_var.
    """
    old_value = test_var.get()
    test_var.set(f"sr-{id:03d}")
    sleep = randint(1, 5)
    time.sleep(sleep)
    return {
        "input": f"{id:03d}",
        "old": old_value,
        "new": test_var.get(),
        "sleep": sleep,
    }


@app.get("/ar-{id}")
async def get_ar(id: int) -> dict[str, Any]:
    """
    Asynchronous request with explicit test_var.
    """
    old_value = test_var.get()
    test_var.set(f"ar-{id:03d}")
    sleep = randint(1, 5)
    await asyncio.sleep(sleep)
    return {
        "input": f"{id:03d}",
        "old": old_value,
        "new": test_var.get(),
        "sleep": sleep,
    }


@app.get("/sr/sf")
def get_sr_sf(
    old_new: Annotated[tuple[str | None, None], Depends(sf)],
) -> dict[str, Any]:
    """
    Synchronous request with sync fixture.
    """
    old, new = old_new
    sleep = randint(1, 5)
    time.sleep(sleep)
    return {
        "old": old,
        "new": new,
        "test_var": test_var.get(),
        "sleep": sleep,
    }


@app.get("/sr/af")
def get_sr_af(
    old_new: Annotated[tuple[str | None, None], Depends(af)],
) -> dict[str, Any]:
    """
    Synchronous request with async fixture.
    """
    old, new = old_new
    sleep = randint(1, 5)
    time.sleep(sleep)
    return {
        "old": old,
        "new": new,
        "test_var": test_var.get(),
        "sleep": sleep,
    }


@app.get("/ar/sf")
async def get_ar_sf(
    old_new: Annotated[tuple[str | None, None], Depends(sf)],
) -> dict[str, Any]:
    """
    Asynchronous request with sync fixture.
    """
    old, new = old_new
    sleep = randint(1, 5)
    await asyncio.sleep(sleep)
    return {
        "old": old,
        "new": new,
        "test_var": test_var.get(),
        "sleep": sleep,
    }


@app.get("/ar/af")
async def get_arequest_sync(
    old_new: Annotated[tuple[str | None, None], Depends(af)],
) -> dict[str, Any]:
    """
    Asynchronous request with async fixture.
    """
    old, new = old_new
    sleep = randint(1, 5)
    await asyncio.sleep(sleep)
    return {
        "old": old,
        "new": new,
        "test_var": test_var.get(),
        "sleep": sleep,
    }


if __name__ == "__main__":
    import uvicorn

    test_var.set("init")

    uvicorn.run(app, host="localhost", port=8000)
```

### Output

Using a script to run multiple tests:

<details>
<summary>Test Script</summary>

```bash
#!/bin/bash

NUM_REQUESTS=20

for prefix in sr ar; do
    echo "==> Testing /$prefix-{id}"
    for id in $(seq 0 $NUM_REQUESTS); do
        printf '%s\n' "$(curl -s "http://localhost:8000/$prefix-$id")" &
    done
    wait
    echo
done

for request in sr ar; do
    for fixture in sf af; do
        echo "==> Testing /$request/$fixture"
        for id in $(seq 0 $NUM_REQUESTS); do
            printf '%s\n' "$(curl -s "http://localhost:8000/$request/$fixture")" &
        done
        wait
        echo
    done
done
```

</details>

